-- MySQL 8+ schema. Simulated data only; DDL does not import Excel.
CREATE DATABASE IF NOT EXISTS veloop_db; USE veloop_db;
CREATE TABLE IF NOT EXISTS users(user_id VARCHAR(100) PRIMARY KEY,registered_at DATETIME,acquisition_source VARCHAR(100),primary_device VARCHAR(50),platform VARCHAR(50),account_status VARCHAR(50),verification_status VARCHAR(50),onboarding_status VARCHAR(50));
CREATE TABLE IF NOT EXISTS sessions(session_id VARCHAR(100) PRIMARY KEY,user_id VARCHAR(100) NOT NULL,session_start DATETIME,session_end DATETIME,session_duration_seconds INT,device VARCHAR(50),platform VARCHAR(50),session_status VARCHAR(50),FOREIGN KEY(user_id) REFERENCES users(user_id));
CREATE TABLE IF NOT EXISTS feature_events(event_id VARCHAR(100) PRIMARY KEY,user_id VARCHAR(100) NOT NULL,session_id VARCHAR(100),event_datetime DATETIME,feature_name VARCHAR(100),event_name VARCHAR(100),event_status VARCHAR(50),device VARCHAR(50),platform VARCHAR(50),reward_related_flag VARCHAR(10),xp_related_flag VARCHAR(10),FOREIGN KEY(user_id) REFERENCES users(user_id),FOREIGN KEY(session_id) REFERENCES sessions(session_id));
CREATE TABLE IF NOT EXISTS task_activity(activity_id VARCHAR(100) PRIMARY KEY,user_id VARCHAR(100) NOT NULL,task_id VARCHAR(100),task_category VARCHAR(100),task_viewed_at DATETIME,task_started_at DATETIME,task_completed_at DATETIME,task_status VARCHAR(50),failure_reason VARCHAR(255),reward_status VARCHAR(50),session_id VARCHAR(100),FOREIGN KEY(user_id) REFERENCES users(user_id));
CREATE TABLE IF NOT EXISTS reward_ledger(transaction_id VARCHAR(100) PRIMARY KEY,user_id VARCHAR(100) NOT NULL,amount DECIMAL(18,6),unit VARCHAR(30),status VARCHAR(30),source VARCHAR(100),created_at DATETIME,reference_id VARCHAR(100),reversal_of_transaction_id VARCHAR(100),idempotency_key VARCHAR(150) UNIQUE,FOREIGN KEY(user_id) REFERENCES users(user_id),FOREIGN KEY(reversal_of_transaction_id) REFERENCES reward_ledger(transaction_id));
CREATE TABLE IF NOT EXISTS withdrawals(withdrawal_id VARCHAR(100) PRIMARY KEY,user_id VARCHAR(100) NOT NULL,requested_amount DECIMAL(18,6),unit VARCHAR(30),method VARCHAR(50),requested_at DATETIME,processing_at DATETIME,final_at DATETIME,status VARCHAR(30),reason_category VARCHAR(100),provider_reference VARCHAR(150),FOREIGN KEY(user_id) REFERENCES users(user_id));
CREATE TABLE IF NOT EXISTS referrals(referral_id VARCHAR(100) PRIMARY KEY,referrer_user_id VARCHAR(100) NOT NULL,referred_user_id VARCHAR(100) NOT NULL,created_at DATETIME,registered_at DATETIME,activated_at DATETIME,converted_at DATETIME,status VARCHAR(30),source VARCHAR(100),FOREIGN KEY(referrer_user_id) REFERENCES users(user_id),FOREIGN KEY(referred_user_id) REFERENCES users(user_id));
SELECT COUNT(*) AS users FROM users;
SELECT task_status,COUNT(*) FROM task_activity GROUP BY task_status;
